description:
{
  "image_category": "SIGN_ILLUSTRATION",
  "summary": "Hình ảnh minh họa ba biển báo nguy hiểm thuộc nhóm W.228 theo QCVN 41:2024/BGTVT, dùng để cảnh báo các hiện tượng địa chất nguy hiểm trên đường bộ.",
  "items": [
    {
      "identifier": "Biển số W.228a",
      "visual_or_geometric_features": "Hình tam giác đều, viền đỏ, nền vàng, biểu tượng đen: khối đá đang trượt từ sườn núi xuống đường.",
      "meaning_or_specification": "Báo trước đoạn đường có hiện tượng đất đá từ trên ta luy dương sụt lở bất ngờ gây nguy hiểm cho xe cộ và người đi đường, đặc biệt ở đoạn đường miền núi."
    },
    {
      "identifier": "Biển số W.228b",
      "visual_or_geometric_features": "Hình tam giác đều, viền đỏ, nền vàng, biểu tượng đen: khối đá đang trượt từ sườn núi xuống đường (giống W.228a nhưng có thể khác chi tiết nhỏ tùy phiên bản).",
      "meaning_or_specification": "Cùng mục đích với W.228a, dùng để báo trước đoạn đường có hiện tượng đá lở; người tham gia giao thông phải chú ý, hạn chế dừng đỗ xe trong khu vực đá lở sau mưa lớn."
    },
    {
      "identifier": "Biển số W.228c",
      "visual_or_geometric_features": "Hình tam giác đều, viền đỏ, nền vàng, biểu tượng đen: các viên sỏi đá bắn lên từ mặt đường khi xe đi qua.",
      "meaning_or_specification": "Báo trước nơi có kết cấu mặt đường rời rạc, khi phương tiện đi qua làm các viên đá, sỏi bắn lên gây nguy hiểm và mất an toàn cho người và phương tiện tham gia giao thông."
    }
  ]
}
